package com.ke.ticketsystemke.service;
import com.ke.ticketsystemke.dto.*;import com.ke.ticketsystemke.entity.*;import com.ke.ticketsystemke.repository.*;import org.springframework.http.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;import java.util.function.Predicate;import java.util.stream.*;
@Service public class WarrantyTrackerService{private static final ZoneId ZONE=ZoneId.of("Asia/Kolkata");private static final Set<String>SORTS=Set.of("MOST_OVERDUE","OLDEST_CLAIM","NEWEST_CLAIM","FOLLOW_UP_DATE","EXPECTED_VISIT_DATE","LAST_UPDATED","DAYS_PENDING","TICKET_NUMBER","MANUFACTURER","WARRANTY_OWNER");private final WarrantyClaimRepository claims;private final WarrantyReplacementRepository replacements;private final WarrantyAttachmentRepository attachments;private final WarrantyClaimEventRepository events;private final EmployeeRepository employees;private final AccessService access;private final WarrantyPendingActionCalculator pending;private final WarrantyDocumentRequirementService documents;
public WarrantyTrackerService(WarrantyClaimRepository c,WarrantyReplacementRepository r,WarrantyAttachmentRepository a,WarrantyClaimEventRepository e,EmployeeRepository employees,AccessService access,WarrantyPendingActionCalculator p,WarrantyDocumentRequirementService d){claims=c;replacements=r;attachments=a;events=e;this.employees=employees;this.access=access;pending=p;documents=d;}
@Transactional(readOnly=true)public WarrantyTrackerPageResponse list(WarrantyTrackerFilter f,String actor){authorize(actor);validate(f);List<WarrantyTrackerRowResponse> rows=baseRows();rows=rows.stream().filter(filters(f)).filter(r->view(r,f.getView())).sorted(sort(f.getSort())).toList();int from=Math.min(f.getPage()*f.getSize(),rows.size()),to=Math.min(from+f.getSize(),rows.size()),pages=(rows.size()+f.getSize()-1)/f.getSize();return new WarrantyTrackerPageResponse(f.getPage(),f.getSize(),rows.size(),pages,f.getPage()==0,f.getPage()>=Math.max(0,pages-1),rows.subList(from,to));}
@Transactional(readOnly=true)public Map<String,Long> counts(WarrantyTrackerFilter f,String actor){authorize(actor);validate(f);List<WarrantyTrackerRowResponse> rows=baseRows().stream().filter(filters(f)).toList();Map<String,Long> out=new LinkedHashMap<>();for(WarrantyTrackerView v:WarrantyTrackerView.values())out.put(v.name(),rows.stream().filter(r->view(r,v)).count());return out;}
@Transactional(readOnly=true)public WarrantyTrackerFilterOptionsResponse options(String actor){authorize(actor);List<WarrantyTrackerRowResponse> rows=baseRows();return new WarrantyTrackerFilterOptionsResponse(values(rows,WarrantyTrackerRowResponse::manufacturer),rows.stream().filter(r->r.ownerId()!=null).collect(Collectors.toMap(WarrantyTrackerRowResponse::ownerId,r->new WarrantyTrackerFilterOptionsResponse.Option(r.ownerId(),r.ownerName()==null?r.ownerId():r.ownerName()),(a,b)->a,TreeMap::new)).values().stream().toList(),values(rows,WarrantyTrackerRowResponse::ticketCategory),values(rows,WarrantyTrackerRowResponse::ticketStatus),values(rows,r->r.state()==null?null:r.state().name()),values(rows,r->r.result()==null?null:r.result().name()),values(rows,r->r.pendingAction()==null?null:r.pendingAction().code()));}
private List<WarrantyTrackerRowResponse> baseRows(){List<WarrantyClaim> all=claims.findAllForTracker();if(all.isEmpty())return List.of();List<Long> ids=all.stream().map(WarrantyClaim::getId).toList();Map<Long,WarrantyReplacement> repl=replacements.findByWarrantyClaim_IdInAndActiveTrue(ids).stream().collect(Collectors.toMap(r->r.getWarrantyClaim().getId(),r->r));Map<Long,Set<WarrantyAttachmentCategory>> docs=new HashMap<>();for(Object[] x:attachments.findActiveCategoriesByClaimIds(ids))docs.computeIfAbsent((Long)x[0],k->EnumSet.noneOf(WarrantyAttachmentCategory.class)).add((WarrantyAttachmentCategory)x[1]);Map<Long,Instant> activity=events.findLastActivityByClaimIds(ids).stream().collect(Collectors.toMap(x->(Long)x[0],x->(Instant)x[1]));Set<String> ownerIds=all.stream().map(WarrantyClaim::getWarrantyOwnerEmployeeId).filter(Objects::nonNull).map(s->s.toLowerCase(Locale.ROOT)).collect(Collectors.toSet());Map<String,String> owners=employees.findByEmployeeIdLowercaseIn(ownerIds).stream().collect(Collectors.toMap(e->e.getEmployeeId().toLowerCase(Locale.ROOT),Employee::getName));LocalDate today=LocalDate.now(ZONE);List<WarrantyTrackerRowResponse> rows=new ArrayList<>();for(WarrantyClaim c:all){Ticket t=c.getTicket();WarrantyReplacement r=repl.get(c.getId());Set<WarrantyAttachmentCategory> present=docs.getOrDefault(c.getId(),Set.of());int required=documents.billRuleApplies(c)&&!present.contains(WarrantyAttachmentCategory.BILL_IMAGE)?1:0,recommended=recommendedMissing(c,r,present);WarrantyPendingActionResponse pa=pending.calculate(c,r);Instant start=c.getMarkedWarrantyAt()!=null?c.getMarkedWarrantyAt():c.getCreatedAt(),end=c.isActive()?Instant.now():c.getClaimClosedAt()!=null?c.getClaimClosedAt():c.getResolvedAt()!=null?c.getResolvedAt():Instant.now();long days=start==null?0:Math.max(0,ChronoUnit.DAYS.between(start.atZone(ZONE).toLocalDate(),end.atZone(ZONE).toLocalDate()));String category=t.getCategoryRecord()!=null?t.getCategoryRecord().getDisplayName():t.getCategory()==null?null:t.getCategory().name(),status=t.getStatusRecord()!=null?t.getStatusRecord().getDisplayName():t.getStatus().name(),owner=c.getWarrantyOwnerEmployeeId();rows.add(new WarrantyTrackerRowResponse(c.getId(),t.getId(),t.getTicketNumber(),t.getCustomerName(),t.getMobileNumber(),t.getVillageOrArea(),t.getProductType(),category,status,c.getClaimSequence(),c.isActive(),c.getState(),c.getResult(),c.getManufacturerName(),c.getProductSerialNumber(),c.getModelNumber(),c.getManufacturerComplaintNumber(),owner,owner==null?null:owners.getOrDefault(owner.toLowerCase(Locale.ROOT),owner),c.getExpectedVisitDate(),c.getActualVisitDate(),c.getNextFollowUpDate(),c.getReplacementApprovalDate(),c.getExpectedReplacementDate(),r==null?null:first(r.getNewProductName(),r.getNewProductType()),r==null?null:r.getNewModelNumber(),r==null?null:r.getNewSerialNumber(),required,recommended,pa,days,activity.getOrDefault(c.getId(),c.getUpdatedAt()),c.getCreatedAt(),c.getUpdatedAt()));}return rows;}
private boolean view(WarrantyTrackerRowResponse r,WarrantyTrackerView v){LocalDate today=LocalDate.now(ZONE);return switch(v){case ALL_ACTIVE->r.active();case ACTION_REQUIRED->r.active()&&r.pendingAction()!=null&&!"NO_IMMEDIATE_ACTION".equals(r.pendingAction().code());case FOLLOW_UP_DUE->r.active()&&r.nextFollowUpDate()!=null&&!r.nextFollowUpDate().isAfter(today);case VISIT_OVERDUE->r.active()&&r.expectedVisitDate()!=null&&r.expectedVisitDate().isBefore(today)&&r.actualVisitDate()==null;case DOCUMENTS_PENDING->r.requiredDocumentsMissingCount()>0;case COMPLAINT_NOT_REGISTERED->r.active()&&blank(r.complaintNumber());case VISIT_PENDING->r.active()&&(r.state()==WarrantyClaimState.VISIT_PENDING||r.state()==WarrantyClaimState.VISIT_SCHEDULING_REQUIRED);case AWAITING_RESULT->r.active()&&(r.state()==WarrantyClaimState.VISIT_COMPLETED_AWAITING_RESULT||r.state()==WarrantyClaimState.AWAITING_RESULT);case REPLACEMENT_PENDING->r.active()&&(r.state()==WarrantyClaimState.REPLACEMENT_APPROVED_AWAITING_PRODUCT||r.state()==WarrantyClaimState.REPLACEMENT_RECEIVED||r.result()==WarrantyClaimResult.REPLACEMENT_DONE&&r.state()==WarrantyClaimState.DELIVERY_PENDING||"COMPLETE_REPLACEMENT_DETAILS".equals(code(r)));case READY_TO_DELIVER->r.active()&&(r.state()==WarrantyClaimState.MANUFACTURER_REPAIR_COMPLETED||r.state()==WarrantyClaimState.REPLACEMENT_RECEIVED||r.state()==WarrantyClaimState.DELIVERY_PENDING);case AWAITING_CUSTOMER_DECISION->r.active()&&(r.state()==WarrantyClaimState.WARRANTY_REJECTED_AWAITING_DECISION||r.state()==WarrantyClaimState.CUSTOMER_DECISION_PENDING);case REJECTED->r.result()==WarrantyClaimResult.WARRANTY_REJECTED;case RESOLVED->r.result()!=null&&r.result()!=WarrantyClaimResult.PENDING;case CLOSED->!r.active()||r.state()==WarrantyClaimState.CLOSED;};}
private Predicate<WarrantyTrackerRowResponse> filters(WarrantyTrackerFilter f){String q=norm(f.getSearch());return r->{if(q!=null&&!search(r,q))return false;if(f.getManufacturer()!=null&&!eq(r.manufacturer(),f.getManufacturer()))return false;if(f.getOwner()!=null&&!eq(r.ownerId(),f.getOwner()))return false;if(f.getCategory()!=null&&!eq(r.ticketCategory(),f.getCategory()))return false;if(f.getTicketStatus()!=null&&!eq(r.ticketStatus(),f.getTicketStatus()))return false;if(f.getState()!=null&&!eq(r.state()==null?null:r.state().name(),f.getState()))return false;if(f.getResult()!=null&&!eq(r.result()==null?null:r.result().name(),f.getResult()))return false;if(f.getPendingAction()!=null&&!eq(code(r),f.getPendingAction()))return false;if(Boolean.TRUE.equals(f.getOverdue())&&(r.pendingAction()==null||!r.pendingAction().overdue()))return false;if(Boolean.TRUE.equals(f.getDocumentsMissing())&&r.requiredDocumentsMissingCount()==0)return false;if(f.getComplaintRegistered()!=null&&f.getComplaintRegistered()!=!blank(r.complaintNumber()))return false;if(f.getReplacementPresent()!=null&&f.getReplacementPresent()!=!blank(r.replacementProduct()))return false;if(f.getActive()!=null&&f.getActive()!=r.active())return false;return range(r.nextFollowUpDate(),f.getFollowUpFrom(),f.getFollowUpTo())&&range(r.expectedVisitDate(),f.getVisitFrom(),f.getVisitTo())&&range(date(r.claimCreatedAt()),f.getCreatedFrom(),f.getCreatedTo())&&range(date(r.claimUpdatedAt()),f.getUpdatedFrom(),f.getUpdatedTo());};}
private Comparator<WarrantyTrackerRowResponse> sort(String s){Comparator<WarrantyTrackerRowResponse> c=switch(s){case"OLDEST_CLAIM"->Comparator.comparing(WarrantyTrackerRowResponse::claimCreatedAt,Comparator.nullsLast(natural()));case"NEWEST_CLAIM"->Comparator.comparing(WarrantyTrackerRowResponse::claimCreatedAt,Comparator.nullsLast(reverse()));case"FOLLOW_UP_DATE"->Comparator.comparing(WarrantyTrackerRowResponse::nextFollowUpDate,Comparator.nullsLast(natural()));case"EXPECTED_VISIT_DATE"->Comparator.comparing(WarrantyTrackerRowResponse::expectedVisitDate,Comparator.nullsLast(natural()));case"LAST_UPDATED"->Comparator.comparing(WarrantyTrackerRowResponse::lastWarrantyActivityAt,Comparator.nullsLast(reverse()));case"DAYS_PENDING"->Comparator.comparingLong(WarrantyTrackerRowResponse::daysPending).reversed();case"TICKET_NUMBER"->Comparator.comparing(WarrantyTrackerRowResponse::ticketNumber,Comparator.nullsLast(String.CASE_INSENSITIVE_ORDER));case"MANUFACTURER"->Comparator.comparing(WarrantyTrackerRowResponse::manufacturer,Comparator.nullsLast(String.CASE_INSENSITIVE_ORDER));case"WARRANTY_OWNER"->Comparator.comparing(WarrantyTrackerRowResponse::ownerName,Comparator.nullsLast(String.CASE_INSENSITIVE_ORDER));default->Comparator.comparing((WarrantyTrackerRowResponse r)->r.pendingAction()!=null&&r.pendingAction().overdue()?0:1).thenComparingInt(r->r.pendingAction()==null?999:r.pendingAction().priority()).thenComparing(r->r.pendingAction()==null?null:r.pendingAction().dueDate(),Comparator.nullsLast(natural()));};return c.thenComparing(WarrantyTrackerRowResponse::claimId);}
private boolean search(WarrantyTrackerRowResponse r,String q){return Stream.of(r.ticketNumber(),r.customerName(),r.mobileNumber(),r.productType(),r.manufacturer(),r.complaintNumber(),r.originalSerial(),r.replacementSerial(),r.ownerName(),r.ownerId()).filter(Objects::nonNull).map(this::normalize).anyMatch(v->v.contains(q));}private int recommendedMissing(WarrantyClaim c,WarrantyReplacement r,Set<WarrantyAttachmentCategory> p){int n=0;if(!p.contains(WarrantyAttachmentCategory.WARRANTY_CARD_IMAGE))n++;if(!p.contains(WarrantyAttachmentCategory.PRODUCT_SERIAL_NUMBER_IMAGE))n++;if(c.getManufacturerComplaintNumber()!=null&&!p.contains(WarrantyAttachmentCategory.MANUFACTURER_SERVICE_SLIP))n++;if(r!=null&&!p.contains(WarrantyAttachmentCategory.REPLACEMENT_PROOF))n++;if(r!=null&&r.getNewSerialNumber()==null&&!p.contains(WarrantyAttachmentCategory.REPLACEMENT_SERIAL_NUMBER_IMAGE))n++;return n;}private void validate(WarrantyTrackerFilter f){if(f.getPage()<0||f.getSize()<1||f.getSize()>100)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Page must be non-negative and size must be between 1 and 100");if(f.getSearch()!=null&&f.getSearch().trim().length()>120)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Search is too long");if(!SORTS.contains(f.getSort()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unsupported tracker sort");}private void authorize(String a){access.requireAllowed(a,AccessKey.VIEW_TICKETS);access.requireAllowed(a,AccessKey.VIEW_WARRANTY_TRACKER);}private List<String>values(List<WarrantyTrackerRowResponse>r,java.util.function.Function<WarrantyTrackerRowResponse,String>f){return r.stream().map(f).filter(x->!blank(x)).distinct().sorted(String.CASE_INSENSITIVE_ORDER).toList();}private String code(WarrantyTrackerRowResponse r){return r.pendingAction()==null?null:r.pendingAction().code();}private String norm(String s){return blank(s)?null:normalize(s.trim());}private String normalize(String s){return s.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]","");}private boolean eq(String a,String b){return a!=null&&a.equalsIgnoreCase(b.trim());}private boolean blank(String s){return s==null||s.isBlank();}private boolean range(LocalDate v,LocalDate from,LocalDate to){return(from==null||v!=null&&!v.isBefore(from))&&(to==null||v!=null&&!v.isAfter(to));}private LocalDate date(Instant i){return i==null?null:i.atZone(ZONE).toLocalDate();}private String first(String a,String b){return blank(a)?b:a;}private static<T extends Comparable<? super T>>Comparator<T>natural(){return Comparator.naturalOrder();}private static<T extends Comparable<? super T>>Comparator<T>reverse(){return Comparator.reverseOrder();}}
